    name: "GasFresnal",
    id: 9,
    type: "custom",
    vertexShader: "\n\tvarying vec3 vPositionW;\n\tvarying vec3 vNormalW;\n\tvarying vec2 vUv;\n\n\tuniform float time;\n\tuniform bool uWobble;\n\tuniform float uScale;\n\n\tvec4 mod289(vec4 x) { return x - floor(x * (1.0 / 289.0)) * 289.0; }\n\tvec4 permute(vec4 x) { return mod289(((x*34.0)+10.0)*x); }\n\tvec4 taylorInvSqrt(vec4 r) { return 1.79284291400159 - 0.85373472095314 * r; }\n\tvec2 fade(vec2 t) { return t*t*t*(t*(t*6.0-15.0)+10.0); }\n\n\tfloat cnoise(vec2 P) {\n\t\tvec4 Pi = floor(P.xyxy) + vec4(0.0, 0.0, 1.0, 1.0);\n\t\tvec4 Pf = fract(P.xyxy) - vec4(0.0, 0.0, 1.0, 1.0);\n\t\tPi = mod289(Pi); // To avoid truncation effects in permutation\n\t\tvec4 ix = Pi.xzxz;\n\t\tvec4 iy = Pi.yyww;\n\t\tvec4 fx = Pf.xzxz;\n\t\tvec4 fy = Pf.yyww;  \n\t\tvec4 i = permute(permute(ix) + iy); \n\t\tvec4 gx = fract(i * (1.0 / 41.0)) * 2.0 - 1.0 ;\n\t\tvec4 gy = abs(gx) - 0.5 ;\n\t\tvec4 tx = floor(gx + 0.5);\n\t\tgx = gx - tx;   \n\t\tvec2 g00 = vec2(gx.x,gy.x);\n\t\tvec2 g10 = vec2(gx.y,gy.y);\n\t\tvec2 g01 = vec2(gx.z,gy.z);\n\t\tvec2 g11 = vec2(gx.w,gy.w); \n\t\tvec4 norm = taylorInvSqrt(vec4(dot(g00, g00), dot(g01, g01), dot(g10, g10), dot(g11, g11)));    \n\t\tfloat n00 = norm.x * dot(g00, vec2(fx.x, fy.x));\n\t\tfloat n10 = norm.y * dot(g10, vec2(fx.y, fy.y));\n\t\tfloat n01 = norm.z * dot(g01, vec2(fx.z, fy.z));\n\t\tfloat n11 = norm.w * dot(g11, vec2(fx.w, fy.w));    \n\t\tvec2 fade_xy = fade(Pf.xy);\n\t\tvec2 n_x = mix(vec2(n00, n01), vec2(n10, n11), fade_xy.x);\n\t\tfloat n_xy = mix(n_x.x, n_x.y, fade_xy.y);\n\t\treturn 2.3 * n_xy;\n\t}\n\n\tvoid main() {\n\t\tif (uWobble) {\n\t\t\tfloat turbulence = cnoise(-(uv * uScale) + time / 2.0);\n\t\t\tfloat noise = cnoise((uv * uScale) + time / 2.0);\n\t\t\tfloat displacement = (noise + turbulence);\n\n\t\t\tvec3 newPosition = position + normal * displacement / 100.0;\n\t\t\tgl_Position = projectionMatrix * modelViewMatrix * vec4(newPosition, 1.0);\n\t\t} else {\n\t\t\tgl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);\n\t\t}\n\n\t\tvPositionW = normalize(vec3(modelViewMatrix * vec4(position, 1.0)).xyz);\n\t\tvNormalW = normalize(normalMatrix * normal);\n\t\tvUv = uv;\n\t}",
    fragmentShader: "\n\tvarying vec3 vPositionW;\n\tvarying vec3 vNormalW;\n\tvarying vec2 vUv;\n\n\tuniform vec3 uBase;\n\tuniform vec3 uAccent;\n\tuniform float uScale;\n\tuniform float uPower;\n\tuniform float time;\n\tuniform bool uStars;\n\n\tvec4 mod289(vec4 x) { return x - floor(x * (1.0 / 289.0)) * 289.0; }\n\tvec4 permute(vec4 x) { return mod289(((x*34.0)+10.0)*x); }\n\tvec4 taylorInvSqrt(vec4 r) { return 1.79284291400159 - 0.85373472095314 * r; }\n\tvec2 fade(vec2 t) { return t*t*t*(t*(t*6.0-15.0)+10.0); }\n\n\tfloat cnoise(vec2 P) {\n\t\tvec4 Pi = floor(P.xyxy) + vec4(0.0, 0.0, 1.0, 1.0);\n\t\tvec4 Pf = fract(P.xyxy) - vec4(0.0, 0.0, 1.0, 1.0);\n\t\tPi = mod289(Pi); // To avoid truncation effects in permutation\n\t\tvec4 ix = Pi.xzxz;\n\t\tvec4 iy = Pi.yyww;\n\t\tvec4 fx = Pf.xzxz;\n\t\tvec4 fy = Pf.yyww;  \n\t\tvec4 i = permute(permute(ix) + iy); \n\t\tvec4 gx = fract(i * (1.0 / 41.0)) * 2.0 - 1.0 ;\n\t\tvec4 gy = abs(gx) - 0.5 ;\n\t\tvec4 tx = floor(gx + 0.5);\n\t\tgx = gx - tx;   \n\t\tvec2 g00 = vec2(gx.x,gy.x);\n\t\tvec2 g10 = vec2(gx.y,gy.y);\n\t\tvec2 g01 = vec2(gx.z,gy.z);\n\t\tvec2 g11 = vec2(gx.w,gy.w); \n\t\tvec4 norm = taylorInvSqrt(vec4(dot(g00, g00), dot(g01, g01), dot(g10, g10), dot(g11, g11)));    \n\t\tfloat n00 = norm.x * dot(g00, vec2(fx.x, fy.x));\n\t\tfloat n10 = norm.y * dot(g10, vec2(fx.y, fy.y));\n\t\tfloat n01 = norm.z * dot(g01, vec2(fx.z, fy.z));\n\t\tfloat n11 = norm.w * dot(g11, vec2(fx.w, fy.w));    \n\t\tvec2 fade_xy = fade(Pf.xy);\n\t\tvec2 n_x = mix(vec2(n00, n01), vec2(n10, n11), fade_xy.x);\n\t\tfloat n_xy = mix(n_x.x, n_x.y, fade_xy.y);\n\t\treturn 2.3 * n_xy;\n\t}\n\n\tvoid main() {\n\t\tfloat turbulence = cnoise(-(vUv * uScale) + time / 2.0);\n\t\tfloat noise = cnoise((vUv * uScale) + time / 2.0);\n\t\tfloat displacement = (noise + turbulence);\n\n\t\tfloat fresnelTerm = (uPower + min(dot(vPositionW, normalize(vNormalW)), 0.0));\n\n\t\tvec3 base = uBase * 4.0;\n\t\tvec3 gas = uAccent * displacement;\n\n\t\tif (gas.r < base.r) {\n\t\t\tgas.r = base.r;\n\t\t}\n\n\t\tif (gas.g < base.g) {\n\t\t\tgas.g = base.g;\n\t\t}\n\n\t\tif (gas.b < base.b) {\n\t\t\tgas.b = base.b;\n\t\t}\n\n\t\tif (uStars) {\n\t\t\tfloat starSize = (1.0 / 0.01) * uScale / 10.0;\n\n\t\t\tfloat cluster = cnoise(vUv * starSize + time);\n\t\t\tfloat clampedCluster = clamp(abs(pow(cluster, 1.0 / 0.09)), 0.0, 1.0);\n\t\t\tif (clampedCluster == 1.0) {\n\t\t\t\tclampedCluster = 0.0;    \n\t\t\t}\n\t\t\tclampedCluster *= 3.0;\n\t\t\tvec4 stars = vec4(clampedCluster);\n\n\t\t\tgl_FragColor = stars + vec4(gas * vec3(fresnelTerm), 1.0);\n\t\t} else {\n\t\t\tgl_FragColor = vec4(gas * vec3(fresnelTerm), 1.0);\n\t\t}\n\t}",
